+fn max_outstanding_deliveries(
+    queue_capacity: usize,
+    endpoint_count: usize,
+    max_concurrency: usize,
+) -> usize {
+    queue_capacity
+        .saturating_mul(endpoint_count.max(1))
+        .max(max_concurrency)
+        .min(MAX_OUTSTANDING_DELIVERY_TASKS)
