+        .strip_prefix('[')
+        .and_then(|inner| inner.strip_suffix(']'))
+        .unwrap_or(host);
+    match ip_literal.parse::<IpAddr>() {
+        Ok(ip) => classify_ip(ip),
+        Err(_) => HostClass::Public,
