+            if ip.is_unspecified() || ip.is_broadcast() || ip.is_multicast() {
+                HostClass::Invalid
+            } else if ip.is_loopback() || ip.is_private() || ip.is_link_local() {
+                HostClass::NonPublic
+            } else {
+                HostClass::Public
+            }
+        }
+        IpAddr::V6(ip) => {
+            if let Some(mapped) = ip.to_ipv4_mapped() {
+                return classify_ip(IpAddr::V4(mapped));
