+/// metadata such as `token_bucket_config`, `password_reset_url`, or
+/// `credentials_verification_status` from being stripped while still redacting common
+/// credential field names and compound names such as `access_token`, `private_key`,
+/// `db_password`, or `webhook_signature`.
+fn is_sensitive_field(key: &str) -> bool {
+    let normalized: String = key
+        .chars()
+        .map(|ch| match ch {
+            '-' | '.' | ' ' => '_',
+            _ => ch.to_ascii_lowercase(),
+        })
+        .collect();
+    let normalized = normalized.trim_matches('_');
+
+    if normalized.is_empty() {
+        return false;
+    }
+
+    const EXACT_FIELDS: &[&str] = &[
+        "api_key",
+        "apikey",
+        "api_token",
+        "auth",
+        "auth_header",
+        "authorization",
+        "authorization_header",
+        "bearer",
+        "bearer_token",
+        "client_secret",
+        "cookie",
+        "credential",
+        "credentials",
+        "csrf",
+        "csrf_token",
+        "hashed_password",
+        "id_token",
+        "idtoken",
+        "jwt",
+        "jwt_token",
+        "passphrase",
+        "password",
+        "password_digest",
+        "password_hash",
+        "passwd",
+        "private_key",
+        "private_key_pem",
+        "privatekey",
+        "refresh_token",
+        "refreshtoken",
+        "secret",
+        "secret_key",
+        "secret_value",
+        "secretkey",
+        "session_token",
+        "set_cookie",
+        "signature",
+        "token",
+        "token_value",
+        "webhook_secret",
+        "webhook_signature",
+        "x_api_key",
+        "xapikey",
+    ];
+
+    if EXACT_FIELDS.contains(&normalized) {
+        return true;
+    }
+
+    const SENSITIVE_SUFFIXES: &[&str] = &[
+        "_api_key",
+        "_auth",
+        "_authorization",
+        "_bearer",
+        "_cookie",
+        "_credential",
+        "_credentials",
+        "_csrf",
+        "_jwt",
+        "_passphrase",
+        "_password",
+        "_passwd",
+        "_private_key",
+        "_secret",
+        "_secret_key",
+        "_signature",
+        "_token",
+    ];
+
+    if SENSITIVE_SUFFIXES
+        .iter()
+        .any(|suffix| normalized.ends_with(suffix))
+    {
+        return true;
+    }
+
+    const SENSITIVE_PREFIXES: &[&str] = &[
+        "access_token_",
+        "api_key_",
+        "authorization_",
+        "bearer_",
+        "client_secret_",
+        "csrf_",
+        "id_token_",
+        "jwt_",
+        "private_key_",
+        "refresh_token_",
+        "secret_key_",
+        "set_cookie_",
+        "x_api_key_",
+    ];
+
+    SENSITIVE_PREFIXES
+        .iter()
+        .any(|prefix| normalized.starts_with(prefix))
+}
