+                    endpoint_index = delivery.endpoint_index,
+                    event = %delivery.event,
+                    delivery_id = %delivery.id,
+                    error_kind = request_error_kind(&request_error),
+                    attempts = attempt + 1,
+                    "webhook delivery retries exhausted"
+                );
+                return;
+            }
