+async fn run_dispatcher(
+    mut rx: mpsc::Receiver<Msg>,
+    endpoints: Arc<Vec<Endpoint>>,
+    client: reqwest::Client,
+    semaphore: Arc<Semaphore>,
+    options: DeliveryOptions,
+    flush_timeout: Duration,
+    max_outstanding: usize,
