+        tokio::select! {
+            result = deliveries.join_next(), if !deliveries.is_empty() => {
+                if let Some(result) = result {
+                    log_delivery_task_result(result);
+                }
+            }
+            message = rx.recv() => {
+                match message {
+                    Some(Msg::Event(event)) => {
+                        spawn_deliveries(
+                            &mut deliveries,
+                            event,
+                            &endpoints,
+                            &client,
+                            &semaphore,
+                            options,
+                        );
+                    }
+                    Some(Msg::Flush(reply)) => {
+                        flush_deliveries(&mut deliveries, flush_timeout).await;
+                        let _ = reply.send(());
+                    }
+                    None => {
+                        flush_deliveries(&mut deliveries, flush_timeout).await;
+                        break;
+                    }
+                }
+            }
+        }
+    }
