+    Continue,
+    /// The envd connection ended normally (end-of-stream, process exit).
+    /// Cleanup has already been performed.
+    NormalExit(String),
+    /// An actual error occurred (e.g., WS send failure).
+    /// Cleanup has already been performed.
+    Error(String),
