+        handle_terminal_socket(
+            socket,
+            session_id,
+            sandbox_id,
+            container_name,
+            user,
+            envd_access_token,
+            envd_url,
+            tracker,
+            http_client,
+            idle_timeout_secs,
+        )
+    }))
+}
