+		 VALUES ($1, $2, $3)
+		 ON CONFLICT (version) DO UPDATE SET sha256 = EXCLUDED.sha256, source = EXCLUDED.source`,
+		fp.version, fp.sum, fp.source,
+	)
+	if err != nil {
+		return fmt.Errorf("record fingerprint for version %d: %w", fp.version, err)
+	}
